static struct mtk_mcu dpm_mcu[] = {
	{
	 .firmware_name = CONFIG_DPM_DM_FIRMWARE,
	 .load_buffer = dpm_data_binary,
	 .run_address = (void *)DPM_DM_SRAM_BASE,
	 .run_size = 422,
	 },
	{
	 .firmware_name = CONFIG_DPM_PM_FIRMWARE,
	 .load_buffer = dpm_program_binary,
	 .run_address = (void *)DPM_PM_SRAM_BASE,
	 .run_size = 18910,
	 .priv = mtk_dpm,
	 .reset = dpm_reset,
	 },
};

void dpm_reset(struct mtk_mcu *mcu)
{
	struct dpm_regs *dpm = mcu->priv;

	/* write bootargs */
	mmio_write_32(&dpm->twam_window_len, 0x0);
	mmio_write_32(&dpm->twam_mon_type, 0x0);

	/* free RST */
	mmio_setbits_32(&dpm->sw_rstn, DPM_SW_RSTN_RESET);
}

int dpm_init(void)
{
	int i;
	struct mtk_mcu *dpm;

	NOTICE("MT8188 %s\n", __func__);

	if (dpm_4ch_init())
		return -1;

	/* config DPM SRAM layout */
	mmio_clrsetbits_32(&mtk_dpm->sw_rstn, DPM_MEM_RATIO_MASK,
			   DPM_MEM_RATIO_CFG1);

	for (i = 0; i < ARRAY_SIZE(dpm_mcu); i++) {
		dpm = &dpm_mcu[i];
		if (mtk_init_mcu(dpm))
			return -1;
	}

	if (dpm_4ch_para_setting())
		return -1;

	return 0;
}

MTK_PLAT_SETUP_0_INIT(dpm_init);
